const price = 10;

function read() {
  return price;
}

function report() {
  console.log(read(), price);

  var price = 20;

  if (price > 15) {
    try {
      console.log(read(), price);
    } catch (error) {
      console.log(read(), error.name);
    }

    let price = 30;
    console.log(read(), price);
  }

  console.log(read(), price);
}

report();
